(27, 1, '2026-11-06 01:36:02', '2026-11-06 01:36:02', '<!-- wp:template-part {\"slug\":\"header\",\"theme\":\"the-family-blog\",\"tagName\":\"header\"} /-->\n\n<!-- wp:group {\"metadata\":{\"patternName\":\"the-family-blog/hero-blog\",\"name\":\"Blog masthead\",\"description\":\"A split masthead with the blog name, an introduction, two calls to action and a full-height family photograph.\",\"categories\":[\"the-family-blog-sections\",\"featured\",\"banner\"]},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|superbspacing-large\",\"right\":\"var:preset|spacing|superbspacing-small\",\"bottom\":\"var:preset|spacing|superbspacing-large\",\"left\":\"var:preset|spacing|superbspacing-small\"},\"blockGap\":\"var:preset|spacing|superbspacing-small\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"backgroundColor\":\"mono-4\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-mono-4-background-color has-background\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--superbspacing-large);padding-right:var(--wp--preset--spacing--superbspacing-small);padding-bottom:var(--wp--preset--spacing--superbspacing-large);padding-left:var(--wp--preset--spacing--superbspacing-small)\"><!-- wp:columns {\"verticalAlignment\":\"center\",\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|superbspacing-small\",\"left\":\"var:preset|spacing|superbspacing-small\"}}}} -->\n<div class=\"wp-block-columns alignwide are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"50%\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-small\",\"padding\":{\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\"}}}} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"padding-top:0;padding-right:0;padding-bottom:0;padding-left:0;flex-basis:50%\"><!-- wp:paragraph {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xxsmall\"}}} -->\n<p>A journal in progress</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":1,\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xxsmall\",\"margin\":{\"top\":\"var:preset|spacing|superbspacing-xsmall\"}}},\"textColor\":\"mono-1\"} -->\n<h1 class=\"wp-block-heading has-mono-1-color has-text-color\" style=\"margin-top:var(--wp--preset--spacing--superbspacing-xsmall)\">Ordinary days, written down.</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|superbspacing-small\"}}},\"textColor\":\"mono-2\",\"fontSize\":\"superbfont-small\"} -->\n<p class=\"has-mono-2-color has-text-color has-superbfont-small-font-size\" style=\"margin-bottom:var(--wp--preset--spacing--superbspacing-small)\">Two small children, one draughty house, and the parts of the week worth keeping. Written slowly, mostly at the kitchen table.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-small\",\"margin\":{\"bottom\":\"var:preset|spacing|superbspacing-small\"}}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"verticalAlignment\":\"center\"}} -->\n<div class=\"wp-block-group\" style=\"margin-bottom:var(--wp--preset--spacing--superbspacing-small)\"><!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"fontSize\":\"superbfont-xsmall\"} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-superbfont-xsmall-font-size has-custom-font-size wp-element-button\" href=\"#\">Start reading</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"4px\"},\"blockGap\":\"0\"},\"border\":{\"bottom\":{\"color\":\"var:preset|color|primary\",\"width\":\"1px\",\"style\":\"solid\"},\"top\":{\"width\":\"0px\",\"style\":\"none\"},\"right\":{\"width\":\"0px\",\"style\":\"none\"},\"left\":{\"width\":\"0px\",\"style\":\"none\"}}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\" style=\"border-top-style:none;border-top-width:0px;border-right-style:none;border-right-width:0px;border-bottom-color:var(--wp--preset--color--primary);border-bottom-style:solid;border-bottom-width:1px;border-left-style:none;border-left-width:0px;padding-bottom:4px\"><!-- wp:paragraph {\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\"}},\"textColor\":\"primary\",\"fontSize\":\"superbfont-xsmall\"} -->\n<p class=\"has-primary-color has-text-color has-superbfont-xsmall-font-size\" style=\"font-style:normal;font-weight:500\"><a href=\"#\">Newest entry →</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"75%\",\"style\":{\"spacing\":{\"blockGap\":\"15px\",\"padding\":{\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"padding-right:0;padding-bottom:0;padding-left:0;flex-basis:75%\"><!-- wp:cover {\"url\":\"http://localhost/NusantaraCraft/NsCraft/wp-content/themes/the-family-blog/assets/images/hero-family.webp\",\"alt\":\"A parent and two young children walking hand in hand through a sunlit front room\",\"dimRatio\":10,\"overlayColor\":\"base\",\"focalPoint\":{\"x\":0.99,\"y\":0.5},\"minHeight\":640,\"contentPosition\":\"bottom left\",\"isDark\":false,\"style\":{\"border\":{\"radius\":\"0px\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover is-light has-custom-content-position is-position-bottom-left\" style=\"border-radius:0px;min-height:640px\"><img class=\"wp-block-cover__image-background\" alt=\"A parent and two young children walking hand in hand through a sunlit front room\" src=\"http://localhost/NusantaraCraft/NsCraft/wp-content/themes/the-family-blog/assets/images/hero-family.webp\" style=\"object-position:99% 50%\" data-object-fit=\"cover\" data-object-position=\"99% 50%\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-base-background-color has-background-dim-10 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:paragraph {\"placeholder\":\"Write title…\",\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-large-font-size\"></p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"patternName\":\"the-family-blog/the-family-blog-featured-002\",\"name\":\"The Family Blog Featured 2\",\"categories\":[\"featured\"]},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|superbspacing-xxlarge\",\"bottom\":\"var:preset|spacing|superbspacing-xxlarge\",\"left\":\"var:preset|spacing|superbspacing-small\",\"right\":\"var:preset|spacing|superbspacing-small\"},\"blockGap\":\"var:preset|spacing|superbspacing-large\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--superbspacing-xxlarge);padding-right:var(--wp--preset--spacing--superbspacing-small);padding-bottom:var(--wp--preset--spacing--superbspacing-xxlarge);padding-left:var(--wp--preset--spacing--superbspacing-small)\"><!-- wp:columns {\"align\":\"wide\"} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"width\":\"40%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:40%\"><!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"left\"}},\"textColor\":\"contrast\",\"fontSize\":\"superbfont-xlarge\"} -->\n<h2 class=\"wp-block-heading has-text-align-left has-contrast-color has-text-color has-superbfont-xlarge-font-size\">What to expect from our website &amp; blog</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xsmall\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xxsmall\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"left\"}},\"textColor\":\"featured\",\"fontSize\":\"superbfont-medium\"} -->\n<h3 class=\"wp-block-heading has-text-align-left has-featured-color has-text-color has-superbfont-medium-font-size\">214</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"left\"}},\"textColor\":\"contrast\",\"fontSize\":\"superbfont-medium\"} -->\n<h3 class=\"wp-block-heading has-text-align-left has-contrast-color has-text-color has-superbfont-medium-font-size\">entries since 2019, most of them short</h3>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"left\":\"var:preset|spacing|superbspacing-xxsmall\"}},\"border\":{\"left\":{\"color\":\"var:preset|color|featured\",\"width\":\"4px\"},\"top\":[],\"right\":[],\"bottom\":[]}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"border-left-color:var(--wp--preset--color--featured);border-left-width:4px;padding-left:var(--wp--preset--spacing--superbspacing-xxsmall)\"><!-- wp:paragraph {\"className\":\"has-secondary-color has-text-color\",\"style\":{\"typography\":{\"textAlign\":\"left\"}},\"textColor\":\"secondary\",\"fontSize\":\"superbfont-small\"} -->\n<p class=\"has-text-align-left has-secondary-color has-text-color has-superbfont-small-font-size\">Nothing here is sponsored and nothing is a system. It is one family writing down the weekday hours before they go, twenty minutes at a time.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|superbspacing-xlarge\",\"left\":\"var:preset|spacing|superbspacing-small\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xsmall\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:image {\"scale\":\"cover\",\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"align\":\"center\",\"style\":{\"border\":{\"radius\":\"0px\"}}} -->\n<figure class=\"wp-block-image aligncenter size-large has-custom-border\"><img src=\"http://localhost/NusantaraCraft/NsCraft/wp-content/themes/the-family-blog/assets/images/the-family-blog-destination1.jpg\" alt=\"\" style=\"border-radius:0px;object-fit:cover\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xxsmall\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"left\"}},\"textColor\":\"contrast\",\"fontSize\":\"superbfont-medium\",\"fontFamily\":\"alegreya\"} -->\n<h3 class=\"wp-block-heading has-text-align-left has-contrast-color has-text-color has-alegreya-font-family has-superbfont-medium-font-size\">Out of doors</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"has-secondary-color has-text-color\",\"style\":{\"typography\":{\"textAlign\":\"left\"}},\"textColor\":\"secondary\",\"fontSize\":\"superbfont-xsmall\"} -->\n<p class=\"has-text-align-left has-secondary-color has-text-color has-superbfont-xsmall-font-size\">Walks that were meant to be short, and the long argument about whether it counts as a hike if nobody wanted to go.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"left\"}},\"textColor\":\"primary\",\"fontSize\":\"superbfont-small\"} -->\n<h3 class=\"wp-block-heading has-text-align-left has-primary-color has-text-color has-superbfont-small-font-size\"><a href=\"#\">Read on →</a></h3>\n<!-- /wp:heading --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xsmall\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:image {\"scale\":\"cover\",\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"align\":\"center\",\"style\":{\"border\":{\"radius\":\"0px\"}}} -->\n<figure class=\"wp-block-image aligncenter size-large has-custom-border\"><img src=\"http://localhost/NusantaraCraft/NsCraft/wp-content/themes/the-family-blog/assets/images/the-family-blog-destination2.jpg\" alt=\"\" style=\"border-radius:0px;object-fit:cover\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xxsmall\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"left\"}},\"textColor\":\"contrast\",\"fontSize\":\"superbfont-medium\",\"fontFamily\":\"alegreya\"} -->\n<h3 class=\"wp-block-heading has-text-align-left has-contrast-color has-text-color has-alegreya-font-family has-superbfont-medium-font-size\">What actually gets eaten</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"has-secondary-color has-text-color\",\"style\":{\"typography\":{\"textAlign\":\"left\"}},\"textColor\":\"secondary\",\"fontSize\":\"superbfont-xsmall\"} -->\n<p class=\"has-text-align-left has-secondary-color has-text-color has-superbfont-xsmall-font-size\">The suppers that get made on repeat, the recipes my mother posts in the mail, and honest notes on what the children pushed to the side of the plate.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"left\"}},\"textColor\":\"primary\",\"fontSize\":\"superbfont-small\"} -->\n<h3 class=\"wp-block-heading has-text-align-left has-primary-color has-text-color has-superbfont-small-font-size\"><a href=\"#\">Read on →</a></h3>\n<!-- /wp:heading --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xsmall\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:image {\"scale\":\"cover\",\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"align\":\"center\",\"style\":{\"border\":{\"radius\":\"0px\"}}} -->\n<figure class=\"wp-block-image aligncenter size-large has-custom-border\"><img src=\"http://localhost/NusantaraCraft/NsCraft/wp-content/themes/the-family-blog/assets/images/the-family-blog-destination3.jpg\" alt=\"\" style=\"border-radius:0px;object-fit:cover\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xxsmall\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"left\"}},\"textColor\":\"contrast\",\"fontSize\":\"superbfont-medium\",\"fontFamily\":\"alegreya\"} -->\n<h3 class=\"wp-block-heading has-text-align-left has-contrast-color has-text-color has-alegreya-font-family has-superbfont-medium-font-size\">Slow trips</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"has-secondary-color has-text-color\",\"style\":{\"typography\":{\"textAlign\":\"left\"}},\"textColor\":\"secondary\",\"fontSize\":\"superbfont-xsmall\"} -->\n<p class=\"has-text-align-left has-secondary-color has-text-color has-superbfont-xsmall-font-size\">One bag, low expectations, and somewhere within a tank of fuel. The trips are small and the write-ups are honest about the parts that went wrong.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"left\"}},\"textColor\":\"primary\",\"fontSize\":\"superbfont-small\"} -->\n<h3 class=\"wp-block-heading has-text-align-left has-primary-color has-text-color has-superbfont-small-font-size\"><a href=\"#\">Read on →</a></h3>\n<!-- /wp:heading --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"patternName\":\"the-family-blog/the-family-blog-featured-003\",\"name\":\"The Family Blog Featured 3\",\"categories\":[\"featured\"]},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|superbspacing-large\",\"right\":\"var:preset|spacing|superbspacing-small\",\"bottom\":\"var:preset|spacing|superbspacing-large\",\"left\":\"var:preset|spacing|superbspacing-small\"},\"blockGap\":\"var:preset|spacing|superbspacing-small\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"backgroundColor\":\"mono-4\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-mono-4-background-color has-background\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--superbspacing-large);padding-right:var(--wp--preset--spacing--superbspacing-small);padding-bottom:var(--wp--preset--spacing--superbspacing-large);padding-left:var(--wp--preset--spacing--superbspacing-small)\"><!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|superbspacing-small\",\"left\":\"var:preset|spacing|superbspacing-small\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"verticalAlignment\":\"center\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-small\",\"padding\":{\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\"}}}} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xxsmall\"}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"left\"}},\"fontSize\":\"superbfont-xlarge\"} -->\n<h2 class=\"wp-block-heading has-text-align-left has-superbfont-xlarge-font-size\">It all happens at <br> the kitchen table</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"has-secondary-color has-text-color\",\"style\":{\"typography\":{\"textAlign\":\"left\"}},\"textColor\":\"secondary\",\"fontSize\":\"superbfont-small\"} -->\n<p class=\"has-text-align-left has-secondary-color has-text-color has-superbfont-small-font-size\">Lessons in the morning, potatoes in the afternoon, letters to grandparents when it rains. Most of what ends up on this blog started at the same scrubbed table, and the entries read like it.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:buttons {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xxsmall\"}}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"spacing\":{\"padding\":{\"left\":\"var:preset|spacing|superbspacing-xsmall\",\"right\":\"var:preset|spacing|superbspacing-xsmall\",\"top\":\"var:preset|spacing|superbspacing-xsmall\",\"bottom\":\"var:preset|spacing|superbspacing-xsmall\"}}},\"fontSize\":\"superbfont-small\"} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-superbfont-small-font-size has-custom-font-size wp-element-button\" style=\"padding-top:var(--wp--preset--spacing--superbspacing-xsmall);padding-right:var(--wp--preset--spacing--superbspacing-xsmall);padding-bottom:var(--wp--preset--spacing--superbspacing-xsmall);padding-left:var(--wp--preset--spacing--superbspacing-xsmall)\">Start reading →</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {\"textColor\":\"primary\",\"className\":\"is-style-outline\",\"styl