nter\"><!-- wp:buttons {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xxsmall\"}}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"width\":100,\"style\":{\"spacing\":{\"padding\":{\"left\":\"var:preset|spacing|superbspacing-xsmall\",\"right\":\"var:preset|spacing|superbspacing-xsmall\",\"top\":\"var:preset|spacing|superbspacing-xsmall\",\"bottom\":\"var:preset|spacing|superbspacing-xsmall\"}}},\"fontSize\":\"superbfont-small\"} -->\n<div class=\"wp-block-button has-custom-width wp-block-button__width-100\"><a class=\"wp-block-button__link has-superbfont-small-font-size has-custom-font-size wp-element-button\" style=\"padding-top:var(--wp--preset--spacing--superbspacing-xsmall);padding-right:var(--wp--preset--spacing--superbspacing-xsmall);padding-bottom:var(--wp--preset--spacing--superbspacing-xsmall);padding-left:var(--wp--preset--spacing--superbspacing-xsmall)\">Sign up →</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|superbspacing-small\",\"left\":\"var:preset|spacing|superbspacing-small\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"verticalAlignment\":\"center\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|superbspacing-medium\",\"bottom\":\"var:preset|spacing|superbspacing-medium\",\"left\":\"var:preset|spacing|superbspacing-medium\",\"right\":\"var:preset|spacing|superbspacing-medium\"},\"blockGap\":\"var:preset|spacing|superbspacing-xsmall\"},\"border\":{\"radius\":\"0px\"}},\"backgroundColor\":\"primary\",\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"left\"}} -->\n<div class=\"wp-block-group has-primary-background-colo