(75, 1, '2026-11-06 04:14:38', '2026-11-06 04:14:38', '<!DOCTYPE html>\n<html lang=\"id\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Contact Us - Nusantara Craft</title>\n    <link href=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css\" rel=\"stylesheet\">\n    <link href=\"https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css\" rel=\"stylesheet\">\n    <style>\n        body {\n            background-color: #faf8f3;\n            font-family: Arial, sans-serif;\n            color: #493626;\n        }\n        .contact-header {\n            background-color: #6b4b35;\n            color: white;\n            padding: 65px 20px;\n            text-align: center;\n        }\n        .contact-header h1 {\n            font-weight: bold;\n            font-size: 38px;\n        }\n        .contact-section {\n            padding: 60px 0;\n        }\n        .contact-card {\n            background: white;\n            border: none;\n            border-radius: 15px;\n            padding: 30px;\n            height: 100%;\n            box-shadow: 0 5px 20px rgba(0,0,0,0.06);\n        }\n        .contact-icon {\n            font-size: 28px;\n            color: #9a704d;\n            margin-bottom: 12px;\n        }\n        .form-control {\n            padding: 12px;\n            border-radius: 8px;\n            border: 1px solid #ded5ca;\n        }\n        .form-control:focus {\n            border-color: #9a704d;\n            box-shadow: 0 0 0 0.2rem rgba(154,112,77,0.15);\n        }\n        .btn-contact {\n            background-color: #6b4b35;\n            color: white;\n            padding: 12px 30px;\n            border-radius: 8px;\n            border: none;\n        }\n        .btn-contact:hover {\n            background-color: #4d3424;\n            color: white;\n        }\n        footer {\n            background-color: #493626;\n            color: white;\n            padding: 20px;\n            text-align: center;\n        }\n    </style>\n</head>\n<body>\n    <!-- Header -->\n    <section>\n        <h1>Hubungi Kami</h1>\n        <p>\n            Kami siap membantu Anda menemukan kerajinan terbaik khas Nusantara.\n        </p>\n    </section>\n    <!-- Contact Section -->\n    <section>\n                <!-- Contact Information -->\n                        <h3>Informasi Kontak</h3>\n                            <h6>Alamat</h6>\n                            <p>\n                                Indonesia\n                            </p>\n                            <h6>Email</h6>\n                            <p>\n                                nusantaracraft@gmail.com\n                            </p>\n                            <h6>Telepon</h6>\n                            <p>\n                                +62 812-3456-7890\n                            </p>\n                            <h6>Jam Operasional</h6>\n                            <p>\n                                Senin - Sabtu, 08.00 - 17.00 WIB\n                            </p>\n                <!-- Contact Form -->\n                        <h3>Kirim Pesan</h3>\n                        <p>\n                            Punya pertanyaan atau ingin mengetahui produk kami?\n                            Silakan kirim pesan melalui formulir berikut.\n                        </p>\n                        <form action=\"#\" method=\"post\">\n                                <label>\n                                    Nama Lengkap\n                                </label>\n                                <input type=\"text\"\n                                    name=\"nama\" placeholder=\"Masukkan nama Anda\"\n                                    required>\n                                <label>\n                                    Email\n                                </label>\n                                <input type=\"email\"\n                                    name=\"email\" placeholder=\"Masukkan email Anda\"\n                                    required>\n                                <label>\n                                    Subjek\n                                </label>\n                                <input type=\"text\"\n                                    name=\"subjek\" placeholder=\"Subjek pesan\"\n                                    required>\n                                <label>\n                                    Pesan\n                                </label>\n                                <textarea name=\"pesan\"\n                                    rows=\"5\" placeholder=\"Tuliskan pesan Anda...\"\n                                    required></textarea>\n                            <button type=\"submit\">\n                                Kirim Pesan\n                            </button>\n                        </form>\n    </section>\n    <!-- Footer -->\n    <footer>\n        <p>\n            &copy; 2026 Nusantara Craft.\n            Melestarikan Budaya, Mendukung Pengrajin Lokal.\n        </p>\n    </footer>\n</body>\n</html>', 'Contact', '', 'inherit', 'closed', 'closed', '', '20-revision-v1', '', '', '2026-11-06 04:14:38', '2026-11-06 04:14:38', '', 20, 'http://localhost/NusantaraCraft/NsCraft/?p=75', 0, 'revision', '', 0);
