",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xsmall\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:image {\"scale\":\"cover\",\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"align\":\"center\",\"style\":{\"border\":{\"radius\":\"0px\"}}} -->\n<figure class=\"wp-block-image aligncenter size-large has-custom-border\"><img src=\"http://localhost/NusantaraCraft/NsCraft/wp-content/themes/the-family-blog/assets/images/the-family-blog-office1.jpg\" alt=\"\" style=\"border-radius:0px;object-fit:cover\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xxsmall\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"textColor\":\"contrast\",\"fontSize\":\"superbfont-small\"} -->\n<h3 class=\"wp-block-heading has-text-align-center has-contrast-color has-text-color has-superbfont-small-font-size\">The hill behind the house</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"textColor\":\"secondary\",\"fontSize\":\"superbfont-xsmall\"} -->\n<p class=\"has-text-align-center has-secondary-color has-text-color has-superbfont-xsmall-font-size\">Twenty minutes up, wind guaranteed, and the view that talked us into buying this house in nine days.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"textColor\":\"primary\",\"fontSize\":\"superbfont-small\"} -->\n<h3 class=\"wp-block-heading has-text-align-center has-primary-color has-text-color has-superbfont-small-font-size\">Read those entries →</h3>\n<!-- /wp:heading --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xsmall\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\"><!-- wp:image {\"scale\":\"cover\",\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"align\":\"center\",\"style\":{\"border\":{\"radius\":\"0px\"}}} -->\n<figure class=\"wp-block-image aligncenter size-large has-custom-border\"><img src=\"http://localhost/NusantaraCraft/NsCraft/wp-content/themes/the-family-blog/assets/images/the-family-blog-office2.jpg\" alt=\"\" style=\"border-radius:0px;object-fit:cover\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xxsmall\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"textColor\":\"contrast\",\"fontSize\":\"superbfont-small\"} -->\n<h3 class=\"wp-block-heading has-text-align-center has-contrast-color has-text-color has-superbfont-small-font-size\">The beach an hour west</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"textColor\":\"secondary\",\"fontSize\":\"superbfont-xsmall\"} -->\n<p class=\"has-text-align-center has-secondary-color has-text-color has-superbfont-xsmall-font-size\">Always colder than promised, always worth it, chips in the car on the way home.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"textColor\":\"primary\",\"fontSize\":\"superbfont-small\"} -->\n<h3 class=\"wp-block-heading has-text-align-center has-primary-color has-text-color has-superbfont-small-font-size\">Read those entries →</h3>\n<!-- /wp:heading --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"patternName\":\"the-family-blog/the-family-blog-contact-001\",\"name\":\"The Family Blog Contact\",\"categories\":[\"contact\"]},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|superbspacing-large\",\"right\":\"var:preset|spacing|superbspacing-small\",\"bottom\":\"var:preset|spacing|superbspacing-large\",\"left\":\"var:preset|spacing|superbspacing-small\"},\"blockGap\":\"0\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"padding-top:var(--wp--preset--spacing--superbspacing-large);padding-right:var(--wp--preset--spacing--superbspacing-small);padding-bottom:var(--wp--preset--spacing--superbspacing-large);padding-left:var(--wp--preset--spacing--superbspacing-small)\"><!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|superbspacing-small\",\"left\":\"var:preset|spacing|superbspacing-small\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"\",\"style\":{\"spacing\":{\"blockGap\":\"15px\",\"padding\":{\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":\"0px\"},\"color\":{\"duotone\":\"unset\"}}} -->\n<figure class=\"wp-block-image size-large has-custom-border\"><img src=\"http://localhost/NusantaraCraft/NsCraft/wp-content/themes/the-family-blog/assets/images/the-family-blog-contact1.jpg\" alt=\"\" style=\"border-radius:0px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-small\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xsmall\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"left\"}},\"textColor\":\"contrast\",\"fontSize\":\"superbfont-xlarge\"} -->\n<h2 class=\"wp-block-heading has-text-align-left has-contrast-color has-text-color has-superbfont-xlarge-font-size\">Say hello</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}},\"textColor\":\"secondary\",\"fontSize\":\"superbfont-small\"} -->\n<p class=\"has-text-align-left has-secondary-color has-text-color has-superbfont-small-font-size\">Notes from readers are the best part of keeping this blog. Tell me what you cooked, what your Tuesday looked like, or which entry you read twice. I answer everything eventually, usually once the children are asleep.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xsmall\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|superbspacing-xsmall\",\"left\":\"var:preset|spacing|superbspacing-xsmall\"}}}} -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xxsmall\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\"},\"blockGap\":\"0\"},\"border\":{\"radius\":\"0px\",\"width\":\"0px\",\"style\":\"none\"}},\"backgroundColor\":\"base\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group has-base-background-color has-background\" style=\"border-style:none;border-width:0px;border-radius:0px;padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:heading {\"level\":3,\"textColor\":\"primary\",\"fontSize\":\"superbfont-xsmall\"} -->\n<h3 class=\"wp-block-heading has-primary-color has-text-color has-superbfont-xsmall-font-size\">Email</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textColor\":\"secondary\",\"fontSize\":\"superbfont-xxsmall\"} -->\n<p class=\"has-secondary-color has-text-color has-superbfont-xxsmall-font-size\">hello@example.com</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xxsmall\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\"},\"blockGap\":\"0\"},\"border\":{\"radius\":\"0px\",\"width\":\"0px\",\"style\":\"none\"}},\"backgroundColor\":\"base\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group has-base-background-color has-background\" style=\"border-style:none;border-width:0px;border-radius:0px;padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:heading {\"level\":3,\"textColor\":\"primary\",\"fontSize\":\"superbfont-xsmall\"} -->\n<h3 class=\"wp-block-heading has-primary-color has-text-color has-superbfont-xsmall-font-size\">The Sunday letter</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textColor\":\"secondary\",\"fontSize\":\"superbfont-xxsmall\"} -->\n<p class=\"has-secondary-color has-text-color has-superbfont-xxsmall-font-size\">One short email a week, no more</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|superbspacing-xsmall\",\"left\":\"var:preset|spacing|superbspacing-xsmall\"}}}} -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xxsmall\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\"},\"blockGap\":\"0\"},\"border\":{\"radius\":\"0px\",\"width\":\"0px\",\"style\":\"none\"}},\"backgroundColor\":\"base\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group has-base-background-color has-background\" style=\"border-style:none;border-width:0px;border-radius:0px;padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:heading {\"level\":3,\"textColor\":\"primary\",\"fontSize\":\"superbfont-xsmall\"} -->\n<h3 class=\"wp-block-heading has-primary-color has-text-color has-superbfont-xsmall-font-size\">Writing hours</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textColor\":\"secondary\",\"fontSize\":\"superbfont-xxsmall\"} -->\n<p class=\"has-secondary-color has-text-color has-superbfont-xxsmall-font-size\">Most mornings, before seven</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xxsmall\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\"},\"blockGap\":\"0\"},\"border\":{\"radius\":\"0px\",\"width\":\"0px\",\"style\":\"none\"}},\"backgroundColor\":\"base\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group has-base-background-color has-background\" style=\"border-style:none;border-width:0px;border-radius:0px;padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:heading {\"level\":3,\"textColor\":\"primary\",\"fontSize\":\"superbfont-xsmall\"} -->\n<h3 class=\"wp-block-heading has-primary-color has-text-color has-superbfont-xsmall-font-size\">Replies</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textColor\":\"secondary\",\"fontSize\":\"superbfont-xxsmall\"} -->\n<p class=\"has-secondary-color has-text-color has-superbfont-xxsmall-font-size\">Within the week, usually at naptime</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></div>\n<!-- /wp:col