(141, 1, '2026-11-07 10:36:10', '2026-11-07 10:36:10', '<!-- wp:template-part {\"slug\":\"header\",\"theme\":\"the-family-blog\",\"tagName\":\"header\"} /-->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"is-style-default\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|superbspacing-xlarge\",\"bottom\":\"var:preset|spacing|superbspacing-large\",\"left\":\"var:preset|spacing|superbspacing-small\",\"right\":\"var:preset|spacing|superbspacing-small\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"blockGap\":\"var:preset|spacing|superbspacing-large\"},\"background\":{\"backgroundImage\":{\"url\":\"http://localhost/NusantaraCraft/NsCraft/wp-content/uploads/2026/11/me.png\",\"id\":136,\"source\":\"file\",\"title\":\"me\"},\"backgroundSize\":\"cover\",\"backgroundPosition\":\"50% 96%\"}},\"backgroundColor\":\"base\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull is-style-default has-base-background-color has-background\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--superbspacing-xlarge);padding-right:var(--wp--preset--spacing--superbspacing-small);padding-bottom:var(--wp--preset--spacing--superbspacing-large);padding-left:var(--wp--preset--spacing--superbspacing-small)\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xsmall\",\"padding\":{\"top\":\"var:preset|spacing|superbspacing-xxlarge\",\"bottom\":\"var:preset|spacing|superbspacing-xxlarge\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"680px\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:var(--wp--preset--spacing--superbspacing-xxlarge);padding-bottom:var(--wp--preset--spacing--superbspacing-xxlarge)\"><!-- wp:paragraph {\"style\":{\"typography\":{\"textTransform\":\"uppercase\",\"letterSpacing\":\"0.08em\",\"fontStyle\":\"normal\",\"fontWeight\":\"500\",\"textAlign\":\"center\"},\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"textColor\":\"black\",\"fontSize\":\"superbfont-xxsmall\"} -->\n<p class=\"has-text-align-center has-black-color has-text-color has-superbfont-xxsmall-font-size\" style=\"margin-top:0;margin-bottom:0;font-style:normal;font-weight:500;letter-spacing:0.08em;text-transform:uppercase\">A journal of ordinary days</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":1,\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"var:preset|spacing|superbspacing-small\"}},\"typography\":{\"textAlign\":\"center\"}},\"textColor\":\"mono-1\",\"fontSize\":\"superbfont-xxlarge\"} -->\n<h1 class=\"wp-block-heading has-text-align-center has-mono-1-color has-text-color has-superbfont-xxlarge-font-size\" style=\"margin-top:0;margin-bottom:var(--wp--preset--spacing--superbspacing-small)\">Nusantara Craft</h1>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-small\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"center\",\"verticalAlignment\":\"center\"}} -->\n<div class=\"wp-block-group\"><!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"fontSize\":\"superbfont-xsmall\"} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-superbfont-xsmall-font-size has-custom-font-size wp-element-button\" href=\"#3\">Read the archive</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|superbspacing-large\",\"bottom\":\"var:preset|spacing|superbspacing-large\",\"left\":\"var:preset|spacing|superbspacing-small\",\"right\":\"var:preset|spacing|superbspacing-small\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"blockGap\":\"var:preset|spacing|superbspacing-xsmall\"}},\"backgroundColor\":\"base\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"680px\"}} -->\n<div class=\"wp-block-group alignfull has-base-background-color has-background\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--superbspacing-large);padding-right:var(--wp--preset--spacing--superbspacing-small);padding-bottom:var(--wp--preset--spacing--superbspacing-large);padding-left:var(--wp--preset--spacing--superbspacing-small)\"><!-- wp:paragraph {\"style\":{\"typography\":{\"textTransform\":\"uppercase\",\"letterSpacing\":\"0.08em\",\"fontStyle\":\"normal\",\"fontWeight\":\"500\"},\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"textColor\":\"featured\",\"fontSize\":\"superbfont-xxsmall\"} -->\n<p class=\"has-featured-color has-text-color has-superbfont-xxsmall-font-size\" style=\"margin-top:0;margin-bottom:0;font-style:normal;font-weight:500;letter-spacing:0.08em;text-transform:uppercase\">How this started</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"var:preset|spacing|superbspacing-xsmall\"}}},\"fontSize\":\"superbfont-medium\"} -->\n<h2 class=\"wp-block-heading has-superbfont-medium-font-size\" style=\"margin-top:0;margin-bottom:var(--wp--preset--spacing--superbspacing-xsmall)\">Berawal dari kecintaan terhadap kerajinan lokal</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textColor\":\"contrast-dark\",\"fontSize\":\"superbfont-small\"} -->\n<p class=\"has-contrast-dark-color has-text-color has-superbfont-small-font-size\">Nusantara Craft hadir dari kecintaan kami terhadap keindahan seni dan budaya Indonesia. Kami percaya bahwa setiap kerajinan tangan memiliki cerita, nilai, dan keunikan tersendiri yang layak untuk dikenal lebih luas. Dari kain batik yang penuh makna, anyaman yang dibuat dengan ketelitian, hingga ukiran kayu yang memiliki nilai seni tinggi, setiap produk mencerminkan kreativitas para pengrajin lokal.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"textColor\":\"contrast-dark\",\"fontSize\":\"superbfont-small\"} -->\n<p class=\"has-contrast-dark-color has-text-color has-superbfont-small-font-size\">Melalui Nusantara Craft, kami ingin menghubungkan karya para pengrajin dengan masyarakat yang menghargai keindahan dan keaslian produk lokal. Kami menghadirkan berbagai pilihan kerajinan tangan berkualitas yang tidak hanya indah, tetapi juga menjadi bagian dari warisan budaya Indonesia. Dengan mendukung Nusantara Craft, Anda turut membantu melestarikan budaya dan mendukung perkembangan UMKM serta pengrajin lokal Indonesia.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|superbspacing-small\",\"bottom\":\"0\"}}},\"fontSize\":\"superbfont-medium\"} -->\n<h3 class=\"wp-block-heading has-superbfont-medium-font-size\" style=\"margin-top:var(--wp--preset--spacing--superbspacing-small);margin-bottom:0\">Apa yang Akan Anda Temukan di Sini</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textColor\":\"contrast-dark\",\"fontSize\":\"superbfont-small\"} -->\n<p class=\"has-contrast-dark-color has-text-color has-superbfont-small-font-size\">Berbagai kerajinan tangan khas Indonesia yang dibuat dengan penuh ketelitian dan kreativitas. Mulai dari kain batik dengan motif yang indah, produk anyaman dengan sentuhan alami, hingga ukiran kayu yang memiliki nilai seni tinggi. Setiap produk kami hadir untuk memberikan sentuhan budaya Nusantara dalam kehidupan sehari-hari.hours, mostly. What actually gets eaten. The half hour between homework and supper that I have stopped trying to organise. Slow trips with one bag and low expectations. Six years of lessons at a table that is also where we peel potatoes.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"textColor\":\"contrast-dark\",\"fontSize\":\"superbfont-small\"} -->\n<p class=\"has-contrast-dark-color has-text-color has-superbfont-small-font-size\">Kami percaya bahwa kerajinan tangan bukan sekadar produk, tetapi juga bagian dari cerita dan warisan budaya yang perlu dijaga. Melalui Nusantara Craft, kami ingin memperkenalkan karya pengrajin lokal kepada lebih banyak orang, sekaligus memberikan ruang bagi UMKM untuk berkembang. Setiap pembelian Anda menjadi langkah kecil untuk mendukung pengrajin Indonesia dan melestarikan kekayaan budaya bangsa.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"patternName\":\"the-family-blog/the-family-blog-featured-005\",\"name\":\"The Family Blog Featured 5\",\"categories\":[\"featured\"]},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|superbspacing-large\",\"right\":\"var:preset|spacing|superbspacing-small\",\"bottom\":\"var:preset|spacing|superbspacing-large\",\"left\":\"var:preset|spacing|superbspacing-small\"},\"blockGap\":\"var:preset|spacing|superbspacing-xsmall\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"backgroundColor\":\"mono-4\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-mono-4-background-color has-background\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--superbspacing-large);padding-right:var(--wp--preset--spacing--superbspacing-small);padding-bottom:var(--wp--preset--spacing--superbspacing-large);padding-left:var(--wp--preset--spacing--superbspacing-small)\"><!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|superbspacing-small\",\"left\":\"var:preset|spacing|superbspacing-small\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":\"0\",\"padding\":{\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\" style=\"padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"left\"}},\"textColor\":\"primary\",\"fontSize\":\"superbfont-small\"} -->\n<h3 class=\"wp-block-heading has-text-align-left has-primary-color has-text-color has-superbfont-small-font-size\">Perjalanan Kami</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"left\"}},\"fontSize\":\"superbfont-xlarge\"} -->\n<h2 class=\"wp-block-heading has-text-align-left has-superbfont-xlarge-font-size\">Menjaga Tradisi, Menghadirkan Karya</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-small\",\"padding\":{\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\"}}}} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}},\"textColor\":\"secondary\",\"fontSize\":\"superbfont-small\"} -->\n<p class=\"has-text-align-left has-secondary-color has-text-color has-superbfont-small-font-size\">Nusantara Craft hadir untuk memperkenalkan keindahan kerajinan tangan Indonesia kepada lebih banyak orang. Kami menghadirkan berbagai produk batik, anyaman, dan ukiran kayu yang dibuat dengan kreativitas serta ketelitian para pengrajin lokal. Setiap produk memiliki keunikan dan cerita tersendiri, menjadi bukti bahwa warisan budaya Indonesia selalu memiliki tempat di kehidupan modern. Melalui setiap karya, kami ingin terus mendukung UMKM dan menjaga tradisi agar tetap hidup dari generasi ke generasi.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:image {\"id\":140,\"aspectRatio\":\"16/9\",\"scale\":\"cover\",\"focalPoint\":{\"x\":0.49,\"y\":0.25},\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"wide\",\"className\":\"is-style-default\",\"style\":{\"border\":{\"radius\":\"8px\",\"width\":\"0px\",\"style\":\"none\"}}} -->\n<figure class=\"wp-block-image alignwide size-full has-custom-border is-style-default\"><img src=\"http://localhost/NusantaraCraft/NsCraft/wp-content/uploads/2026/11/aw.jpeg\" alt=\"\" class=\"wp-image-140\" style=\"border-style:none;border-width:0px;border-radius:8px;aspect-ratio:16/9;object-fit:cover;object-position:49% 25%\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"theme\":\"the-family-blog\",\"area\":\"footer\"} /-->', 'About', '', 'inherit', 'closed', 'closed', '', '103-revision-v1', '', '', '2026-11-07 10:36:10', '2026-11-07 10:36:10', '', 103, 'http://localhost/NusantaraCraft/NsCraft/?p=141', 0, 'revision', '', 0),
